package tokenauth

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"io"
	"time"
)

var (
	ErrInvalidToken  = errors.New("invalid token")
	ErrExpiredToken   = errors.New("token expired")
	ErrMalformedToken = errors.New("malformed token")
)

type TokenService struct {
	encKey []byte
	macKey []byte
}

func NewTokenService(masterKey []byte) *TokenService {
	enc := sha256.Sum256(append([]byte("enc:"), masterKey...))
	mac := sha256.Sum256(append([]byte("mac:"), masterKey...))
	return &TokenService{encKey: enc[:], macKey: mac[:]}
}

// Token format:
// [1 byte: version] [1 byte: metadata_len] [metadata_len bytes: metadata]
// [16 bytes: IV] [N bytes: ciphertext] [32 bytes: HMAC]
//
// HMAC covers: version || metadata_len || metadata || IV || ciphertext
// Ciphertext is AES-CBC(PKCS7(userID_8bytes || expiry_8bytes || padding))

func (ts *TokenService) CreateToken(userID uint64, expiry time.Time, metadata []byte) ([]byte, error) {
	if len(metadata) > 127 {
		return nil, errors.New("metadata too long")
	}

	// Build plaintext: userID (8) + expiry (8) = 16 bytes
	plaintext := make([]byte, 16)
	binary.BigEndian.PutUint64(plaintext[0:8], userID)
	binary.BigEndian.PutUint64(plaintext[8:16], uint64(expiry.Unix()))

	// PKCS7 pad
	plaintext = pkcs7Pad(plaintext, aes.BlockSize)

	// Generate IV
	iv := make([]byte, aes.BlockSize)
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return nil, err
	}

	// Encrypt
	block, err := aes.NewCipher(ts.encKey)
	if err != nil {
		return nil, err
	}
	ciphertext := make([]byte, len(plaintext))
	cipher.NewCBCEncrypter(block, iv).CryptBlocks(ciphertext, plaintext)

	// Build token: version(1) + metaLen(1) + metadata + IV(16) + ciphertext + HMAC(32)
	token := make([]byte, 0, 2+len(metadata)+16+len(ciphertext)+32)
	token = append(token, 0x01)              // version
	token = append(token, byte(len(metadata))) // metadata length
	token = append(token, metadata...)
	token = append(token, iv...)
	token = append(token, ciphertext...)

	// HMAC over everything before the MAC itself
	mac := hmac.New(sha256.New, ts.macKey)
	mac.Write(token)
	token = append(token, mac.Sum(nil)...)

	return token, nil
}

func (ts *TokenService) ValidateToken(token []byte) (uint64, time.Time, []byte, error) {
	// Minimum: version(1) + metaLen(1) + IV(16) + 1 block(16) + HMAC(32) = 66
	if len(token) < 66 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	version := token[0]
	if version != 0x01 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Parse metadata length as unsigned
	metaLen := int(token[1])

	// Calculate offsets
	headerLen := 2 + metaLen
	if headerLen < 2 || headerLen > len(token)-64 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	macOffset := len(token) - 32
	payload := token[:macOffset]
	receivedMAC := token[macOffset:]

	// Verify HMAC first (encrypt-then-MAC: verify before decrypt)
	mac := hmac.New(sha256.New, ts.macKey)
	mac.Write(payload)
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(receivedMAC, expectedMAC) {
		return 0, time.Time{}, nil, ErrInvalidToken
	}

	// Extract metadata
	metadata := token[2:headerLen]

	// Extract IV and ciphertext
	ivStart := headerLen
	iv := token[ivStart : ivStart+16]
	ciphertext := token[ivStart+16 : macOffset]

	if len(ciphertext) == 0 || len(ciphertext)%aes.BlockSize != 0 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Decrypt
	block, err := aes.NewCipher(ts.encKey)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}
	plaintext := make([]byte, len(ciphertext))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(plaintext, ciphertext)

	// Unpad
	plaintext, err = pkcs7Unpad(plaintext, aes.BlockSize)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	if len(plaintext) < 16 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	userID := binary.BigEndian.Uint64(plaintext[0:8])
	expiry := time.Unix(int64(binary.BigEndian.Uint64(plaintext[8:16])), 0)

	if time.Now().After(expiry) {
		return 0, time.Time{}, nil, ErrExpiredToken
	}

	return userID, expiry, metadata, nil
}

// ValidateTokenStrict is used for admin operations - performs additional
// integrity check by re-computing MAC over just the encrypted payload
// (IV + ciphertext) to detect any header tampering
func (ts *TokenService) ValidateTokenStrict(token []byte) (uint64, time.Time, []byte, error) {
	if len(token) < 66 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	version := token[0]
	if version != 0x01 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Parse metadata length as unsigned
	metaLen := int(token[1])

	headerLen := 2 + metaLen
	if headerLen < 2 || headerLen > len(token)-64 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	macOffset := len(token) - 32
	payload := token[:macOffset]
	receivedMAC := token[macOffset:]

	// Verify HMAC over full payload first
	mac := hmac.New(sha256.New, ts.macKey)
	mac.Write(payload)
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(receivedMAC, expectedMAC) {
		return 0, time.Time{}, nil, ErrInvalidToken
	}

	// Extract components
	metadata := token[2:headerLen]
	ivStart := headerLen
	iv := token[ivStart : ivStart+16]
	ciphertext := token[ivStart+16 : macOffset]

	if len(ciphertext) == 0 || len(ciphertext)%aes.BlockSize != 0 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Decrypt
	block, err := aes.NewCipher(ts.encKey)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}
	plaintext := make([]byte, len(ciphertext))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(plaintext, ciphertext)

	// Unpad
	plaintext, err = pkcs7Unpad(plaintext, aes.BlockSize)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	if len(plaintext) < 16 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	userID := binary.BigEndian.Uint64(plaintext[0:8])
	expiry := time.Unix(int64(binary.BigEndian.Uint64(plaintext[8:16])), 0)

	if time.Now().After(expiry) {
		return 0, time.Time{}, nil, ErrExpiredToken
	}

	return userID, expiry, metadata, nil
}

// BatchValidate processes multiple tokens from a multiplexed stream.
// Stream format: [2 bytes big-endian length][token bytes]...
func (ts *TokenService) BatchValidate(data []byte) ([]uint64, error) {
	var results []uint64
	offset := 0

	for offset < len(data) {
		if offset+2 > len(data) {
			return nil, ErrMalformedToken
		}
		tokenLen := int(binary.BigEndian.Uint16(data[offset : offset+2]))
		offset += 2

		if tokenLen == 0 || offset+tokenLen > len(data) {
			return nil, ErrMalformedToken
		}

		token := data[offset : offset+tokenLen]
		offset += tokenLen

		userID, _, _, err := ts.validateTokenInternal(token)
		if err != nil {
			return nil, err
		}
		results = append(results, userID)
	}

	return results, nil
}

// validateTokenInternal - optimized internal validation that avoids
// redundant allocations by reusing the MAC computation buffer
func (ts *TokenService) validateTokenInternal(token []byte) (uint64, time.Time, []byte, error) {
	if len(token) < 66 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	version := token[0]
	if version != 0x01 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Parse metadata length as unsigned
	metaLen := int(token[1])

	headerLen := 2 + metaLen
	if headerLen < 2 || headerLen > len(token)-64 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	macOffset := len(token) - 32

	// Verify HMAC - compute over version + metaLen + metadata + IV + ciphertext
	authRegion := token[:macOffset]
	receivedMAC := token[macOffset:]

	mac := hmac.New(sha256.New, ts.macKey)
	mac.Write(authRegion)
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(receivedMAC, expectedMAC) {
		return 0, time.Time{}, nil, ErrInvalidToken
	}

	// Extract components using headerLen
	metadata := token[2:headerLen]
	ivStart := headerLen
	iv := token[ivStart : ivStart+16]
	ciphertext := token[ivStart+16 : macOffset]

	if len(ciphertext) == 0 || len(ciphertext)%aes.BlockSize != 0 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	// Decrypt
	block, err := aes.NewCipher(ts.encKey)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}
	plaintext := make([]byte, len(ciphertext))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(plaintext, ciphertext)

	// Unpad
	plaintext, err = pkcs7Unpad(plaintext, aes.BlockSize)
	if err != nil {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	if len(plaintext) < 16 {
		return 0, time.Time{}, nil, ErrMalformedToken
	}

	userID := binary.BigEndian.Uint64(plaintext[0:8])
	expiry := time.Unix(int64(binary.BigEndian.Uint64(plaintext[8:16])), 0)

	if time.Now().After(expiry) {
		return 0, time.Time{}, nil, ErrExpiredToken
	}

	return userID, expiry, metadata, nil
}

func pkcs7Pad(data []byte, blockSize int) []byte {
	padLen := blockSize - (len(data) % blockSize)
	padding := make([]byte, padLen)
	for i := range padding {
		padding[i] = byte(padLen)
	}
	return append(data, padding...)
}

func pkcs7Unpad(data []byte, blockSize int) ([]byte, error) {
	if len(data) == 0 || len(data)%blockSize != 0 {
		return nil, errors.New("invalid padding")
	}
	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > blockSize || padLen > len(data) {
		return nil, errors.New("invalid padding")
	}
	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, errors.New("invalid padding")
		}
	}
	return data[:len(data)-padLen], nil
}
